INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (11,'tanzsparte@kutawerk.de','Beatrice','Peana','[]','[]',NULL,1,1,'/media/i1f7050c7c6c6e7c4.png','Ansprechpartner Tanzsparte\n\nklassisches Ballett\n\nContemporary\n\nBea ist am 01.12.1974 in Verona geboren und begann bereits mit fünf Jahren ihre klassische Ballettausbildung in Verona.\n\nIm Alter von 18 Jahren machte sie eine Ausbildung zur Tanzlehrerin und Tänzerin an der Accademia nazionale di danza in Rom.\n\nDanach arbeitete sie als Tänzerin am:\n\n• London Royal Ballett\n\n• San Carlo di Napoli\n\n• Scala di Milano\n\n• Teatro di Roma\n\n• Arena di Verona\n\n• Semperoper Dresden','Ansprechpartner Tanzsparte',1,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (12,'mager@kutawerk.de','Thorsten','Mager','[]','[]',NULL,1,0,'/media/i9385343a4ebc08b7.jpg',NULL,'Leiter Kultursparte',1,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (13,'jonas@kutawerk.de','Uwe','Jonas','[]','[]',NULL,1,0,'/media/i348db21cc8acb07e.jpg',NULL,'Leiter Event- und Techniksparte',1,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (14,'lounge@kutawerk.de','Emma','','[]','[]',NULL,1,0,'/media/i6be93c64609a0481.png',NULL,'Koordination & Ansprechpartner KuTa Lounge',1,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10005,NULL,'Lisa','Stute','[]','[]',NULL,1,1,'/media/ida6dbc10ce7fc222.jpg','Kindertanz\n\nHip Hop\n\nLisa wurde im Jahr 2000 in Dresden geboren. Mit 12 Jahren begann sie ihre tänzerische Laufbahn im GTA an der Lessing Oberschule in Freital. Später wurde sie Mitglied im KuTa Werk e.V. und entdeckte ihre Leidenschaft im Showtanz. Sie tanzte in der Gruppe Temptations und nahm erfolgreich an Projekten wie „Die Puppenfee“ oder auch „November im Blues“, als Tänzerin und Sängerin teil. Sie ist gelernte Erzieherin und derzeit in der Kultur-& Tanzwerkstatt tätig.\n\nLizenzen:\n\n• seit 2022 - Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10006,NULL,'Patrick','Friedrich','[]','[]',NULL,1,1,'/media/i38632b0903e94d6d.png','Breakdance\n\nHip Hop\n\nPatrick stammt aus Coswig und ist seit August 2018 als Trainer für die Breakdancer bei uns tätig. Er unterrichtet die Kinder - es sind fast ausschließlich Jungs - einmal pro Woche. Als Trainer und Choreograph steht Patrick noch am Anfang seiner professionellen Laufbahn, als Tänzer jedoch ist er bereits ein \"alter Hase\". Mit seiner Streetdance-Crew \"44 Skillz\" aus Dresden hat er bereits viele Jahre Erfahrung bei Wettkämpfen, Auftritten und mit diversen Tanz-Projekten sammeln können.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10007,NULL,'Kerstin','','[]','[]',NULL,1,1,'/media/i6c8fa0790a83446a.png','Mager-Baran\n\nJazz Modern Dance\n\nFitness\n\nKerstin besuchte schon mit fünf Jahren das Klassische Ballett der städtischen Musikschule und probierte sich in ihrer Jugend in nahezu allen Tanzrichtungen aus. Parallel zum Studium der Soziologie begann sie selbst 1992 Tanzkurse für Kinder zu geben und besuchte seitdem eine große Zahl tanzpädagogischer Kurse und Ausbildungen, um die vorhandenen Kenntnisse zu erweitern und auf solide Fundamente zu stellen. 1993 war sie in ihrer Heimatstadt Saalfeld Mitgründerin des immer noch erfolgreichen Tanz- und Fitnessvereins CityDance, den sie bis 2005 leitete. Nach ihrem Umzug nach Sachsen arbeitete sie bis 2011 freiberuflich selbständig als Trainerin in den Bereichen Showtanz, Kindertanz und baute dort erfolgreich die Tanzsportabteilung im Bereich Jazz Modern Dance auf. Von 2008 bis 2011 engagierte sie sich ehrenamtlich als Jazz-Modern-Dance-Beauftragte des Landestanzsportverbandes Sachsen e.V. 2012 eröffneten Kerstin zusammen mit Ulrike Faber im KuTaWerk die Tanzsparte, die sie seit 2018 nur noch ehrenamtlich unterstützt.\n\nLizenzen:\n\n• Übungsleiter B Sport in der Prävention, Schwerpunkt: Erwachsene/Ältere, Stressbewältigung/Entspannung.\n\n• Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)\n\n• Trainerassistentin Jazz- and Modern Dance (Deutscher Tanzsportverband im Deutschen Olympischen Sportbund)\n\n• 1997 - Abschluss zweijährige Ausbildung als Leiter im Amateurtanz (Sächs. LV Tanz e.V./Thür. TanzV. e.V.)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10008,'liebert@kutawerk.de','Linda','Liebert','[]','[]',NULL,1,1,'/media/idf52ca83e254927f.png','Verantwortliche Öffentlichkeitsarbeit\n\nHip Hop\n\nLinda wurde 1997 in Freital geboren. Mit fünf Jahren begann sie ihre tänzerische Ausbildung zunächst mit klassischem Ballett im Tanzstudio Freital e.V., später auch Stepptanz und Jazz Modern Dance. Durch die Tanzstunde kam sie zum Standard und Latein und tanzte vier Jahre im Turniertanz bei der Tanzschule Richter. Nach neun Jahren beendete sie ihre Ballett Ausbildung und entschied sich die Stilrichtung zu wechseln. Anfangs besuchte sie das GTA \"HipHop\" des Weißeritzgymnasiums, wechselte dann zum Tanzteam Wilsdruff und dann ins Freitaler KuTa Werk. In der Zeit von 2012-2018 tanzte und nahm sie mit den Gruppen Beat Definitions, Beat Steps, Beat FreaX und Jelly FreaX erfolgreich an Wettkämpfen Teil. 2018 hat sie Ihre Berufsausbildung zum Mediengestalter Digital und Print erfolgreich abgeschlossen. Seit 2013 trainierte Linda schon verschiedene Tanzgruppen in Eigenverantwortung. Derzeit trainiert sie als Haupttrainerin die leistungsorientierten Gruppen „Swaying Thunders“ sowie die SmallGroup „Strive4Beats“ und ist Verantwortlich für die Öffentlichkeitsarbeit im Verein.\n\nLizenzen:\n\n• seit 2013 - Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10009,NULL,'Melanie','Birkigt','[]','[]',NULL,1,1,'/media/i7e9f9225fa10e964.jpg','Hip Hop\n\nMelanie wurde 1994 in Freital geboren und arbeitet hauptberuflich als Gymnasiallehrerin. Ihre tänzerische Laufbahn begann 2007 im GTA „Tanz“ des Weißeritzgymnasiums, das von Kerstin Mager-Baran geleitet wurde. Seit 2012 ist sie Mitglied im KuTa Werk. Dort tanzte sie bei den Hip-Hop Formationen Beats Steps, Beat FreaX und zu letzt bei den Jelly FreaX. Dies ermöglichte ihr die Teilnahme an zahlreichen Auftritten und Wettkämpfen. Darüberhinaus begann Melanie 2012 ihre Tätigkeit als Übungsleiter. Seitdem leitete sie eigenständig verschiedene Tanzgruppen, vor allem im Bereich Hip-Hop. Aktuell ist sie Trainerin der True Colours und Swaying Thunders, sowie 2. Vorsitzende des Vereinsvorstandes der Kultur- und Tanzwerkstatt.\n\nLizenzen:\n\n• seit 2012 - Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10010,NULL,'Mathilda','Kaufhold','[]','[]',NULL,1,1,'/media/i0287cff00245aaa4.png','Contemporary\n\nMathilda ist 2005 in Freital geboren. Schon von klein auf interessierte sie sich für das Tanzen und begann im Alter von 6 Jahren ihre tänzerische Laufbahn. Seit 2022 ist Sie Trainerin bei uns im Team und tanzt aktiv seit 2020 in unserer Gruppe InFlames.\n\nLizenz:\n\n• seit April 2023 - Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10011,NULL,'Lilith','Michel','[]','[]',NULL,1,1,'/media/i582cfe667d456e68.jpg','Hip Hop\n\nLilith ist 2008 in Dresden geboren, seit dem sie 4 Jahre alt ist, tanzt sie mit wachsender Begeisterung. Durch das GTA-Angebot an ihrer Grundschule, kam sie zum KuTaWerk. Angefangen mit den Happy Beats tanzt sie heute bei den Swaying Thunders und den Strive4Beats. Lilith ist seit 2022 mit voller Leidenschaft Trainerin der Night Sky, wo sie Kids im Alter von 7-10 Jahren im Hip-Hop unterrichtet. Ihr ist es wichtig, dass die Kinder immer Spaß haben und sich tänzerisch weiter entwickeln. Mit Freude choreografiert sie neue Tänze und bringt sich gerne im Verein ein.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10012,NULL,'Fabian','Brückner','[]','[]',NULL,1,1,'/media/ie5f1ea1347530c71.jpg','Breakdance\n\nFabian wurde 2007 in Leipzig geboren. Mit 8 Jahren trat er unserem Verein bei und tanzte in der Gruppe Happy Beats. Aktuell ist er aktiv in den Gruppen Swaying Thunder sowie Strive4Beats. Als Tänzer der Happy Beats und Strive4Beats sammelte er schon viele Erfahrungen im Wettkampfgeschehen. Seit 2018 ist Fabian ein essenzielles Mitglied unserer Breakdancer – Floor Rangers. Im Frühjahr 2023 übernahm er eigenständig unsere Breakdance Gruppe Froggies, hier vermittelt er 4-7 Jährigen Kindern die Grundkenntnisse des Breakdances.\n\nLizenz:\n\n• seit April 2023 - Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10013,NULL,'Caroline','Rentschka','[]','[]',NULL,1,1,'/media/ib693c2fc9b81a94b.png','Hip Hop\n\nCaro wurde 2003 in Freital geboren und tanzt/e seit 2013 bereits in den Gruppen Sweet Beats, Coockie Beats, Beat Attacks, Determinations, der Unique Crew und nun bei den Black Galaxy. Seit Januar 2020 ist sie Trainerin im Bereich Hip Hop. Sie absolviert aktuell die Ausbildung zur staatlich anerkannten Erzieherin.\n\nLizenzen:\n\n• seit 2022 - Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10014,NULL,'Lena','Leuschner','[]','[]',NULL,1,1,'/media/i92962258c7783dbb.jpg','Hip Hop\n\nLena wurde 2007 in Dresden geboren. Schon im Grundschulalter war sie sehr tanzbegeistert, weshalb sie ihre tänzerische Laufbahn in einem GTA begann. Später trat sie dem KuTaWerk bei und tanzte viele Jahre in der Gruppe Happy Beats. Zur Zeit ist Lena Mitglied in der Gruppe Swaying Thunder sowie bei den Strive4Beats.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10015,NULL,'Carlotta','Panico','[]','[]',NULL,1,1,'/media/i8afdd6e942adfd53.png','Contemporary\n\nCarlotta wurde 2006 in Dresden geboren. Mit 7 begann sie ihre tänzerische Laufbahn. Im Alter von 10 Jahren trat sie bei einem Theaterstück des Staatsspielhauses Dresden auf. 2019 wurde sie Mitglied und entdeckte den Jazz Modern/Contemporary für sich. Sie tanzt bei den InFlames und nahm erfolgreich als Hauptrolle bei \"November im Blues\" teil.\n\n• seit 2023 - Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10016,NULL,'Kevin','Pudor','[]','[]',NULL,1,1,'/media/i861ff2602cbbf9ac.jpg','Streetdance\n\nKevin ist 2008 in Freital geboren. Als Kind hatte er schon ein hohes Interesse am Tanzen und trat so 2016 der Kultur- und Tanzwerkstatt bei und tanzte bei den HipHop Midis. Derzeit tanzt er bei der Gruppe Black Galaxy und absolviert gerade die Oberstufe. Kevin ist seit 2023 Trainer der StreetDevils und unterrichtet sie im Street Dance.\n\nLizenz:\n\n- Voraussichtlich 2024 Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10017,NULL,'Doreen','Raubold','[]','[]',NULL,1,1,'/media/ibbc35c1e98aa22f0.png','Oriental Dance\n\n1992 hat sie als eine der ersten in Dresden, Bauchunterricht genommen. Was als Spaßidee anfing, hatte sie bald sehr begeistert, das sie bis ihm bis heute treu geblieben ist. Sie tanze in mehreren orientalischen Restaurants, war von 1999 bis 2007 im Märchenensemble der Yenidze und hatte zahlreiche private Auftritte. 2004 schloss sie eine Ausbildung zur Orientalischen Tanzlehrerin ab und unterrichtet seitdem an der VHS, sowie seit einiger Zeit im Kutawerk. In ihrem Unterricht versucht sie den Spaß, die Lockerheit und die Eleganz des Orientalischen Tanzes ihren Schülern zu vermitteln. Neben der Vermittlung der Technik werden auch immer wieder Choreografien einstudiert, um das gelernte anwenden und festigen zu können.\n\n- seit 2006 Kursleiterin für Orientalischen Tanz (Tanzschule für Orientalischen Tanz und Theater)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10018,NULL,'Anna','Makovska','[]','[]',NULL,1,1,'/media/if030bc17fa3f71be.png','Streetdance\n\nAnna startete mit 13 Jahre ihre tänzerische Laufbahn, indem sie GTA des Weißeritzgymnasiums besuchte. Nach einigen Monaten wechselte sie als Mitglied in die Kultur- und Tanzwerkstatt und fing in der Gruppe Temptations an. In den Jahren 2016 bis 2018 erprobte sie sich erstmals in der Rolle als Trainerin wodurch sie dann eigenständig die Gruppe leitete. Seit Januar 2022 ist sie wieder als Trainerin für unsere Tharandter Gruppen zuständig.\n\nLizenz:\n\n- Voraussichtlich 2024 Übungsleiter C-Lizenz im Breitensport (Landessportbund Sachsen und Deutscher Olympischer Sport Bund)',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10019,NULL,'Monique','Helzel','[]','[]',NULL,1,1,'/media/id92aa649ab69907a.jpg','VideoClip\n\nHip Hop\n\nMonique wurde im Januar 2003 in Dresden geboren und konnte bereits mit 4 Jahren die Freude am Tanzen entdecken. Nach einigen Jahren im Kindertanz begann sie, sich in der Stilrichtung Videoclip/Dance4fans auszuleben. Dabei konnte Monique außerdem Teil einer Wettkampfgruppe werden und Erfahrungen bei Contests sammeln. Ihre Erfahrungen konnte sie durch Workshops erweitern, die ihr Einblicke in weitere Tanzstile, wie Commercial Pop, Jazz Dance und Contemporary boten. Seit Juli 2021 ist Monique Trainerin im Bereich Hip Hop, Videoclip und Dance Fitness im KuTa-Werk. 2021 hat Monique zudem erfolgreich ihr Abitur abgeschlossen und studiert seit Oktober 2022 in Erfurt Architektur. In ihrer freien Zeit unterstützt sie den Verein weiterhin als Trainerin.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10020,NULL,'Lea','Ziegenbalg','[]','[]',NULL,1,1,'/media/i337a0f55b54584c3.jpg','Hip Hop\n\nVideoClip\n\nLea wurde 2003 in Dresden geboren und ist bereits seit dem Kleinkindalter begeistert vom Tanzen. Mit 12 Jahren entschied sie sich dann für die Tanzrichtung VideoClip/Dance4Fans und sammelte dabei auch schon einige Erfahrungen im Wettkampfbereich. In diversen Workshops erhielt sie außerdem Einblicke in andere Tanzstile wie Commercial Pop, Jazz Dance oder Contemporary und konnte dadurch ihr Können erweitern. Seit Mitte 2021 ist sie Trainerin im Bereich Hip Hop und VideoClip. Zudem meisterte sie 2021 erfolgreich ihr Abitur und absolviert derzeit ein freiwilliges, soziales Jahr an einer Dresdner Grundschule.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10021,NULL,'Clara','D.','[]','[]',NULL,1,1,'/media/i2f6930b13f971a8e.jpg','Hip Hop\n\nClara wurde 2000 in Dresden geboren und entschloss sich im Alter von 11 Jahren in der Stilrichtung Hip-Hop zu tanzen. 2012 trat sie der Gruppe „Jelly Beats“ (später Jelly FreaX) bei und nahm mit ihr an zahlreichen Wettkämpfen wie dem DDP-Cup oder World of Dance erfolgreich Teil.\n\nSeit 2017 gehört Clara auch zu unseren Trainern und trainiert Hip-Hop Gruppen (derzeit als Co-Trainerin der Flying Colours). 2019 schloss sie ihr Abitur erfolgreich ab und studiert seitdem den Studiengang Gesundheitsmanagement.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10022,'verein@kutawerk.de','Josi','Striemann','[]','[]',NULL,1,1,'/media/if5c93df7c35ffec6.png','Jugendwartin\n\nHip Hop\n\nJazz Modern Dance\n\nJosi wurde 2002 in Dippoldiswalde geboren und nahm bereits ab dem Alter von 3 Jahren Ballettunterricht im Tanzsstudio Freital e.V.. 9 Jahre lang trainierte sie dort klassischen Ballett, bis sie 2014 unserer ehemaligen Gruppe „Jelly Beats“ (später „Jelly FreaX“) beitrat und sich der Stilrichtung Hip Hop anschloss. Selbst war sie unter anderem als „Puppenfee“ im gleichnamigen Stück, einem Tanzprojekt des Soziokulturellen Zentrums und der Elbland Philharmonie Sachsen, zu sehen. Durch Workshops beherrscht sie verschiedene Tanzstile, darunter House Dance, Locking, Breakdance, Waacking und viele mehr. Seit 2017 engagiert sie sich bei uns als Trainerin und widmet sich speziell den Gruppen Match AttaXx (Hip Hop) und Sparkling Fire (Jazz Modern Dance). Ebenfalls tanzt sie seit 2013 bei der Garde des Karnevalsclub Wurgwitz.\n\nJosi hat im Frühjahr 2020 ihr Abitur gemeistert und absolviert derzeit ein Praktikum an einer Grundschule des Landkreises Wilsdruff.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10023,NULL,'Sandra','Vogel','[]','[]',NULL,1,1,'/media/i4890b038d63da67d.png','Zumba\n\nVideoClip\n\nSandra wurde 1989 in Freital geboren. Mit 11 Jahren ging sie regelmäßig ins Luxor Ballett tanzen und machte ihre ersten Erfahrungen im JazzDance und Showtanz Bereich. Ungefähr mit 14 Jahren wechselte sie die Tanzschule und somit auch die Tanzrichtung und entdeckte Videoclipdance/ Dance4 Fans für sich. Neben jahrelangen MDR Fernsehaufnahmen der Sendung „Weihnachten bei uns“ nahm sie ebenso erfolgreich an Dance4Fans Wettkämpfen teil, im Bereich SmallGroup und auch als Solistin. Nebenbei unterrichtete sie die Faschingsgarde Hainsberg mit viel Freude. Nach ihrer Hotelfachausbildung und einigen Jahren Arbeitsleben, kam für sie ein Angebot, die Erfüllung ihres Traumes und sie entschied sich für die ADTV-Tanzlehrerausbildung und schloss diese erfolgreich 2015 in Bayern ab. Sie arbeitete die letzten Jahre erfolgreich als ADTV-Tanzlehrerin in\n\n• Standard\n\n• Latein\n\n• Videoclip\n\n• Dance4Fans\n\n• Zumba\n\n• Discofox\n\n• Salsa\n\n• Latinotänze\n\nDie Punkte Spaß im Unterricht und am Tanzen, gute Stimmung in der Gruppe, die gemeinsame Leidenschaft teilen und fühlen, abfordern und fördern stehen bei ihr an erster Stelle im Kurs.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `users` (`id`, `email`, `first_name`, `last_name`, `roles`, `permissions`, `password`, `active`, `trainer`, `trainer_image_path`, `trainer_bio`, `contact_function`, `contact_person`, `access_from`, `access_until`) VALUES (10024,NULL,'Hannah','Kelly','[]','[]',NULL,1,1,'/media/i4eca9811b4d7b198.png','Jazz Modern Dance\n\nPilates\n\nHannah ist in Australien geboren und hat in ihrer langen Karriere Erfahrung in den verschiedensten Tanzstilen (inklusive Contemporary, Musical, Showtanz und Ballett) sammeln können.\n\nSie hat eine Ausbildung in Klassischem Ballet an der \"New Zealand School of Dance\" absolviert und danach einen \"Bachelor of Fine Arts\" in Tanz an der \"Queensland University of Technology\" erworben.\n\nBevor Hannah 2009 nach Deutschland kam, tanzte sie mit dem \"Royal New Zealand Ballet\", der \"Expressions Dance Company\" und der \"Opera Queensland\".\n\nIn Berlin arbeitete sie als freischaffende Tänzerin in vielen Projekten von zeitgenössischem Tanz bis Showtanz unter anderem im Las Vegas Format \"Stars in Concert\".\n\nVon 2011 bis 2019 war sie als Solistin und Gruppentänzerin an der \"Staatsoperette\" Dresden engagiert.',NULL,0,NULL,NULL);
INSERT  IGNORE INTO `user_departments` (`user_id`, `department_id`) VALUES (1,1);
