INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (1,'Manege des Mutes – Unser Tanztheater 2025','circus-of-courage-2025','news/manege-des-mutes-2025','/media/i34eb6e742a12f347.png','Am 22. Juni 2025 feierten wir die Premiere unseres diesjährigen Tanztheaters „Manege des Mutes“ im Kulturhaus Freital. Am vergangenen Wochenende, am 30. und 31. August, folgten die zweite und dritte Aufführung – und beide Abende waren ein voller Erfolg. Das Publikum war begeistert, und wir haben unglaublich viel positives Feedback erhalten.','<div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left image-full\">\n<img sizes=\"(min-width: 1000px) 1000px, 100vw\" src=\"/media/i34eb6e742a12f347.png\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div><div class=\"content-block n formatted-text \"><span style=\"-webkit-text-stroke-color: rgb(0, 0, 0);\">Am 22. Juni 2025 feierten wir die Premiere unseres diesjährigen Tanztheaters „Manege des Mutes“ im Kulturhaus Freital. Am vergangenen\nWochenende, am 30. und 31. August, folgten die zweite und dritte Aufführung – und beide Abende waren ein voller Erfolg. Das Publikum war begeistert, und wir haben unglaublich viel positives Feedback\nerhalten.</span></div><div class=\"content-block n content-heading \"><h2 class=\"\">Die Geschichte</h2></div><div class=\"content-block n formatted-text \"><span style=\"-webkit-text-stroke-color: rgb(0, 0, 0);\">In diesem Jahr drehte sich alles um einen Zirkus, der plötzlich ohne Zirkusdirektor dastand. Annelie musste die Manege retten und innerhalb von\nzwei Wochen eine völlig neue Show auf die Beine stellen. Zwischen Tradition und Neuanfang kam es natürlich zu Reibungen: Manche wollten Bewährtes festhalten, andere wagten Neues. Doch durch\nZusammenhalt, Kreativität und Mut entstand eine emotionale, spannende und zugleich humorvolle Show. Besonders berührend war die familiäre Ebene: die Mutter-Tochter-Beziehung, die neue Rolle als\nZirkusdirektorin und das Erbe einer ganzen Familie.</span></div><div class=\"content-block n content-heading \"><h2 class=\"\">Eine Gemeinschaftsleistung</h2></div><div class=\"content-block n formatted-text \"><p style=\"margin-bottom: 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n    <span style=\"font-kerning: none;\">Hinter den Kulissen steckt weit mehr als nur das Tanzen auf der Bühne:</span>\n</p>\n\n<ul>\n    <li style=\"margin: 0px 0px 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n        <span style=\"font-kerning: none;\">250 Tänzerinnen und Tänzer im Alter von 3 bis 63 Jahren standen in diesem Jahr auf der Bühne.</span>\n    </li>\n\n    <li style=\"margin: 0px 0px 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n        <span style=\"font-kerning: none;\">Rund 20 Trainerinnen und Trainer investieren das ganze Jahr über Zeit, Herzblut und Ideen in die Vorbereitung.</span>\n    </li>\n\n    <li style=\"margin: 0px 0px 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n        <span style=\"font-kerning: none;\">Ein besonderes Dankeschön gilt Clara und Josi, die sich ausschließlich auf das Tanztheater fokussieren: Sie entwickeln die Storyline, schreiben die Texte,\n        organisieren die Proben und sorgen für den roten Faden des Abends.</span>\n    </li>\n</ul>\n\n<p style=\"margin-bottom: 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n    <span style=\"font-kerning: none;\">Jeder Trainer überträgt dann das zugeteilte Thema in seine Gruppe: Welche Choreografie passt? Wie bringen wir die Szene zum Leben? Dazu gehört auch Musikschnitt,\n    Abstimmung mit der Technik und Feingefühl für den Bühnenmoment.</span>\n</p></div><div class=\"content-block n content-heading \"><h2 class=\"\">Technik &amp; Helfer – das unsichtbare Rückgrat</h2></div><div class=\"content-block n formatted-text \"><p style=\"margin-bottom: 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n    <span style=\"font-kerning: none;\">Ohne die vielen fleißigen Helfer im Hintergrund wäre ein Projekt dieser Größe nicht möglich:</span>\n</p>\n\n<ul>\n    <li style=\"margin: 0px 0px 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n        <span style=\"font-kerning: none;\">Ein Technikteam kümmerte sich um Licht, Ton, Beamer und Mapping. Die Projektionen ermöglichten uns, nahezu ohne Requisiten zu arbeiten und dennoch großartige\n        Bilder auf die Bühne zu zaubern.</span>\n    </li>\n\n    <li style=\"margin: 0px 0px 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n        <span style=\"font-kerning: none;\">Helfer am Einlass und hinter der Bühne sorgten für reibungslose Abläufe.</span>\n    </li>\n\n    <li style=\"margin: 0px 0px 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n        <span style=\"font-kerning: none;\">Zahlreiche Eltern betreuten die Kinder, halfen beim Schminken und kümmerten sich um Verpflegung.</span>\n    </li>\n\n    <li style=\"margin: 0px 0px 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n        <span style=\"font-kerning: none;\">Hinter den Kulissen achteten Helfer darauf, dass jede Tanzgruppe rechtzeitig auf der Bühne stand und Ruhe herrschte, wenn es darauf ankam.</span>\n    </li>\n</ul></div><div class=\"content-block n content-heading \"><h2 class=\"\">Dankbarkeit &amp; Ausblick</h2></div><div class=\"content-block n formatted-text \"><span style=\"-webkit-text-stroke-color: rgb(0, 0, 0);\">Wir sind stolz, dass wir auch in diesem Jahr wieder drei unvergessliche Shows präsentieren durften. Unser Dank gilt allen Tänzerinnen und\nTänzern, Trainern, Helfern, Familien und Unterstützern, die dieses Projekt möglich gemacht haben.<br>\n<br></span>\n<p style=\"margin-bottom: 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n    <span style=\"font-kerning: none;\">Besonders bedanken wir uns für die Spendeneinnahmen – nur durch diese Unterstützung können wir unsere Arbeit fortsetzen und auch in Zukunft große\n    Tanztheaterproduktionen auf die Bühne bringen.</span>\n</p>\n\n<p style=\"margin-bottom: 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n    <span style=\"font-kerning: none;\">Kleine Eindrücke in Form von Videos und Fotos findet ihr auch auf unserem Instagram-Kanal – und natürlich hier im Blog, sobald die Bilder hochgeladen\n    sind.</span>\n</p>\n\n<p style=\"margin-bottom: 12px; font-width: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; -webkit-text-stroke-color: rgb(0, 0, 0);\">\n    <span style=\"font-kerning: none;\">Wir freuen uns schon jetzt auf das nächste Jahr, wenn es wieder heißt: Vorhang auf für die Kultur- und Tanzwerkstatt Freital! 🎭✨</span>\n</p>\n<br class=\"Apple-interchange-newline\" style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"></div><div class=\"content-block n image-gallery \">\n</div></div>[[NEWS_GALLERY]]',1,1,'2025-09-01 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (2,'Wir tanzen zu den Sternen!','dancing-to-the-stars','news/wir-tanzen-zu-den-sternen','/media/icc024ac61a5bde52.png','Genau vor 3 Jahren stand unsere Show „KuTaWards – Tanzschule für Hexerei und Zauberei“ in den Startlöchern: über 200 kleine und große Tanzbegeisterte fieberten der aufwendig vorbereitenden Vorstellung entgegen, die am 22.03.2020 stattfinden sollte… Dann kam ein (Kultur-)Lockdown nach dem anderen und nach zweimaliger Verschiebung, endlosen Tagen des Online-Trainings und vielen Beschränkungen im Kulturbetrieb verabschiedeten wir uns von der fertigen Show. Ende letzten Jahres fiel...','<div><div class=\"content-block n text-image \"><figure class=\"image-frame image-left image-full\">\n<a href=\"/contact/dance/ticket-presale\"><img sizes=\"(min-width: 210px) 210px, 100vw\" src=\"/media/icc024ac61a5bde52.png\" alt=\"\" class=\"\" loading=\"lazy\"></a>    \n\n</figure>\n<div>\n    <div data-name=\"text\" data-action=\"text\" class=\"formatted-text-inline\">\n        <div>\n    Genau vor 3 Jahren stand unsere Show „KuTaWards – Tanzschule für Hexerei und Zauberei“ in den Startlöchern: über 200 kleine und große Tanzbegeisterte fieberten der aufwendig vorbereitenden\n    Vorstellung entgegen, die am 22.03.2020 stattfinden sollte… Dann kam ein (Kultur-)Lockdown nach dem anderen und nach zweimaliger Verschiebung, endlosen Tagen des Online-Trainings und vielen\n    Beschränkungen im Kulturbetrieb verabschiedeten wir uns von der fertigen Show.<br>\n</div>\n\n<div>\n    Ende letzten Jahres fiel dann endlich die Entscheidung, nach langer Zeit mit neuem Konzept und frischen Ideen zurück auf die große Bühne zu kommen. In der Vor-Corona-Zeit hatte es bis zu 4\n    Bühnenveranstaltungen im Jahr gegeben. Jahreszeiten wurden vertanzt, Märchen erfunden und auch schon mal der Weihnachtsmann nach Hollywood geschickt. Auch die künstlerisch sehr hochwertigen\n    Projekte mit der Elblandphilharmonie „Die Puppenfee“ und „November im Blues“ waren noch gut in Erinnerung. Es war klar, dass wir mit hohem Anspruch an uns selbst in eine neue Zeit starten wollen.\n    So setzte sich das gesamte Organisationsteam der Tanzsparte zusammen und entwickelte Ideen. Modern sollte es sein, eine positive Aussage haben, Tanzszenen ineinanderfließen lassen,\n    bühnentechnisch neue Akzente setzen – und es sollte nach Zeiten sozialer Distanzierung verbinden. Aus diesem Grund werden z.B. Gruppen vom Muskelkater e.V., vom Faschingsverein Hainsberg die\n    Funkengarde und Gruppen aus Ganztagsangeboten von 5 Freitaler Schulen gemeinsam mit KuTaWerk auf der Bühne stehen. Für die veranstaltungstechnische Umsetzung unterstützen viele Mitglieder unserer\n    Kultur- und Techniksparte mit ihrem Knowhow, aber auch das Soziokulturelle Zentrum LIFEART. \n</div>\n\n<div>\n    Auf diese Weise entwickelt sich seit Anfang des Jahres mit viel Herzblut und allen künstlerischen Raffinessen die multimediale Tanzshow „Nicht von dieser Welt! – Eine Tanzreise – Auf der Suche\n    nach dem Captain!“, die am 30.04.23 im Kulturhaus aus Kapazitätsgründen nur intern Premiere vor den Angehörigen und Freunden der Mitwirkenden feiert und am 11.06.23 um 15 Uhr ebenso dort der\n    Öffentlichkeit im Rahmen der Kultur(All)Tage präsentiert wird. Weitere Informationen und Kartenreservierung unter:    https://www.kutawerk.de/ Wir freuen uns auf viele Gäste, die uns im\n    Juni auf der interstellaren Reise unserer Crew begleiten möchten! \n</div>\n\n<div>\n    Die Kultur- und Tanzwerkstatt ist ein eingetragener Verein mit etwa 250 Mitgliedern und anerkannt als freier Träger der Jugendhilfe, der sich hauptsächlich im Bereich Kinder- und Jugendtanz sowie\n    regionale (Jugend)-Kulturarbeit betätigt. Wichtigstes Anliegen in unserem Verein ist es - neben dem Erhalt unserer über 20-jährigen Organisation - unseren Mitgliedern eine kulturelle Heimstatt zu\n    geben, wo sie sich kreativ und zusammen mit anderen Menschen entfalten und dabei auch für die Gemeinschaft etwas leisten können, indem sie Geselligkeiten und Veranstaltungen organisieren oder\n    andere dabei unterstützen. Unser Verein – und so verstehen wir unsere Aufgabe – trägt damit für jeden Einzelnen zur positiven Lebensgestaltung und damit zu einer gesunden und lebenswerten\n    Gesellschaft bei.\n</div>\n\n<div>\n    Unser Verein ist Gründungsmitglied im Soziokultur Freital e.V. und eine feste Größe im kommunalen Kulturangebot.\n</div>    </div>\n</div>\n\n<div class=\"clear\"></div>\n</div></div>',1,1,'2023-04-21 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (3,'Wir sind Gewinner beim Vereinswettbewerb - einer von 333 in Sachsen!','association-competition-winner','news/wir-sind-dabei','/media/ia1866e936ece5ffe.jpg','Im April 2022 haben sehr viele sächsische Sportvereine die Möglichkeit zur Teilnahme am Vereinswettbewerb von der Dachmarke des Freistaats Sachsen „So geht sächsisch.“ und dem Landessportbund Sachsen genutzt. – So wie wir. Das Mitmachen lohnte sich! Eine Jury wählte aus den vielen Bewerbungen am Ende 333 Vereine aus, die wiederum mit jeweils 2.500 Euro für satzungsgemäße Zwecke der täglichen Vereinsarbeit ausgezeichnet wurden. Vielen Dank! Wir haben uns sehr gefreut!!!','<div><div class=\"content-block n content-grid \">    <div class=\"content-column\" style=\"width: 49%;\">\n        <div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left image-full\">\n<a href=\"https://www.so-geht-saechsisch.de/\" target=\"_blank\"><img sizes=\"(min-width: 519px) 519px, 100vw\" src=\"/media/ia1866e936ece5ffe.jpg\" alt=\"\" class=\"\" loading=\"lazy\"></a>    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div></div>    </div>\n            \n        <div class=\"content-column last\" style=\"width: 49%;\">\n        <div><div class=\"content-block n formatted-text \"><p class=\"p1\" style=\"caret-color: #000000; color: #000000; -webkit-text-size-adjust: auto; font-stretch: normal; line-height: normal;\">\n    <span class=\"s1\">Im April 2022 haben sehr viele sächsische Sportvereine die Möglichkeit zur Teilnahme am Vereinswettbewerb von der Dachmarke des Freistaats Sachsen „So geht sächsisch.“ und\n    dem Landessportbund Sachsen genutzt. – So wie wir.</span>\n</p>\n\n<p class=\"p1\" style=\"caret-color: #000000; color: #000000; -webkit-text-size-adjust: auto; font-stretch: normal; line-height: normal;\">\n    <span class=\"s1\">Das Mitmachen lohnte sich! Eine Jury wählte aus den vielen Bewerbungen am Ende 333 Vereine aus, die wiederum mit jeweils 2.500 Euro für satzungsgemäße Zwecke der täglichen\n    Vereinsarbeit ausgezeichnet wurden. Vielen Dank! Wir haben uns sehr gefreut!!!</span>\n</p></div></div>    </div>\n    \n\n\n<br class=\"clear\">\n\n</div></div>',1,1,'2022-07-27 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (4,'!!!','crisis-mode','news/krisenmodus',NULL,'Über anderthalb Jahre Krisenmodus... Unser wichtigstes Anliegen in unserem Verein ist es - neben dem Erhalt unserer bald 20-jährigen Organisation - unseren Mitgliedern eine kulturelle Heimstatt zu geben, wo sie sich kreativ und zusammen mit anderen Menschen entfalten können, und dabei auch für die Gemeinschaft etwas leisten, indem sie Geselligkeiten und Veranstaltungen organisieren oder andere dabei unterstützen. Darüber hinaus trägt unser Verein nicht nur zur gesellschaftlichen Teilhabe...','<div><div class=\"content-block n formatted-text \"><p>\n    <span style=\"font-size: 26px;\"><strong>Über anderthalb Jahre Krisenmodus...</strong></span>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    Unser wichtigstes Anliegen in unserem Verein ist es - neben dem Erhalt unserer bald 20-jährigen Organisation - unseren Mitgliedern eine kulturelle Heimstatt zu geben, wo sie sich kreativ und\n    zusammen mit anderen Menschen entfalten können, und dabei auch für die Gemeinschaft etwas leisten, indem sie Geselligkeiten und Veranstaltungen organisieren oder andere dabei unterstützen.\n</p>\n\n<p>\n    Darüber hinaus trägt unser Verein nicht nur zur gesellschaftlichen Teilhabe und Gestaltung bei, er bildet in seiner täglichen Praxis und Arbeit, in verschiedensten Projekten und Angeboten die\n    Menschen kulturell, schafft gemeinschaftliche Werte und Struktur. Auf diese Weise leistet unser Verein einiges zur individuellen Entwicklung, besonders für unsere Kinder im Verein, aber auch für\n    alle anderen.\n</p>\n\n<p>\n    Unser Verein – und so verstehen wir unsere Aufgabe – trägt damit für jeden Einzelnen zur positiven Lebensgestaltung und damit zur Gesundheitsförderung bei.\n</p>\n\n<p>\n    Man könnte auch sagen, gesellschaftlich stellt das kulturelle Leben, die Kultur, wozu in besonderem Maße Kunst und Sport gehören, das Immunsystem einer Gemeinschaft dar, das ganz besonders gerade\n    dann notwendig ist, wenn Krisen gemeinsam zu überstehen sind.\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    Wir erleben in dieser schon viele Monate andauernden Krise, dass viele Probleme mit Maßnahmen durch die Politik beantwortet werden, über die man streiten kann. Die Richtigkeit oder besser – die\n    Wirksamkeit, um auf geeignete Weise angemessen zu reagieren – steht oftmals in Frage. So auch bei den aktuellen Verordnungen und Beschränkungen, die uns als Verein, der für gesellschaftlichen\n    Zusammenhalt und Teilhabe aller steht, einen neuerlichen Stresstest abverlangen.\n</p>\n\n<p>\n    Als Verein, der aus einer Vielzahl von Menschen besteht, die alle unterschiedliche Ansichten haben, möchten und können wir nicht bewerten, welche Maßnahmen der Politik richtig oder falsch sind.\n    Wir möchten allerdings alles in unserer Macht stehende unternehmen, um unseren Mitgliedern das zu sein, was sie in diesen schwierigen Zeiten brauchen: ein Rückzugsort zur Entspannung und\n    Stärkung.\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <strong>Deshalb stellen wir in den Wochen vor Jahresende unser sportliches Programm um und fokussieren uns auf die kulturellen Bildungsaspekte, die besonders der Tanz als Kunstform bietet und\n    rücken trotz verordneter sozialer Distanzierung damit mental besonders zusammen, wenn wir vor Weihnachten weitere gemeinschaftsbildende Akzente setzen. Auf diese Weise möchten wir betonen, dass\n    unsere Vereinsarbeit weder als privater Kontakt oder als „bloßer“ Sport, auch nicht als „nicht systemrelevante“ Kultur zu definieren ist. - Wir bilden über die Kultur Menschen aus – nämlich zu\n    krisenfesten und positiv denkenden sozialen Persönlichkeiten!</strong>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <strong>In diesem Sinne wünschen wir allen Mitgliedern und ihren Familien gemeinsam mit uns eine besinnliche und gute Zeit im Advent!</strong>\n</p>\n\n<p>\n    <strong>Euer KuTaWerk-Team</strong>\n</p></div></div>',1,1,'2021-11-10 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (5,'NEU!!! Pilates ab 20.10. mit Hannah Kelly','pilates-with-hannah-kelly','news/pilates-mit-hannah-kelly','/media/i6891009e5a54ca50.jpg','All-Levels Pilates-Mattenkurs Gönnen Sie sich 1 Stunde, um Ihren Körper und Geist zu schonen. Verbessern Sie mit Pilates Ihre Körperkraft, Körperspannung, Flexibilität und Koordination! Durch das regelmäßige Ausüben von Pilates: - fühlen Sie sich fitter und stärker - verbessern Tonus, Form und Haltung und - fördern Ihr Wohlbefinden Bitte eigenen Matte (Yoga oder Pilates) mitbringen!','<div><div class=\"content-block n content-grid \">    <div class=\"content-column\" style=\"width: 49%;\">\n        <div><div class=\"content-block n formatted-text \"><p>\n    <strong>Was ist Pilates? </strong><u><br></u> <span class=\"tlid-translation\">Pilates ist eine „low impact“, das bedeutet eine gelenkschonende Fitnessmethode, die sich total auf die\n    Verbesserung von Körperkraft, Körperspannung, Flexibilität und Koordination konzentriert.</span>\n</p>\n\n<p>\n    <span class=\"tlid-translation\">Darüber hinaus ist Pilates eine Form der Geist-Körper-Konditionierung, die dazu beitragen kann Stress abzubauen, den mentalen Fokus zu verbessern und ein\n    verbessertes Wohlbefinden zu fördern.</span>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <span class=\"tlid-translation\"><i>\"Es ist der Geist selbst, der den Körper formt</i></span><span class=\"tlid-translation\">\" (Joseph Pilates, Begründer der Pilates-Methode)</span>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <strong>Über mich und meinen Kurs</strong><br>\n    <span class=\"tlid-translation\">Ich bin zertifizierte BASI Pilates Trainerin und arbeite seit fünfzehn Jahren als professionelle Tänzerin. Während meiner Ausbildung und Karriere hat mich das\n    Praktizieren von Pilates maßgeblich dabei unterstützt mit den körperlichen Anforderungen einer Tanzkarriere umgehen zu können.</span>\n</p>\n\n<p>\n    <span class=\"tlid-translation\">Mein Hintergrund als Tänzerin ermöglicht es mir, etwas Besonderes in meinen Unterricht zu bringen: Wissen, Erfahrung und ein einzigartiges Maß an Körperbewusstsein,\n    geschult durch über zwanzig Jahre Training und Performing.</span>\n</p>\n\n<p>\n    <br>\n    <span class=\"tlid-translation\">Meine Pilates-Mattenkurs bietet ein Ganzkörpertraining mit Fokus auf der Verbesserung von Core - Kraft und - Stabilisierung, welche der Schlüssel zu einer besseren\n    Haltung, funktioneller Bewegung und zur Prävention von Schmerzen und Verletzungen (insbesondere im Rücken) sind. Durch das regelmäßige Ausüben von Pilates können Sie ihre Flexibilität erhöhen,\n    sich fitter und stärker fühlen sowie Tonus, Form und Haltung verbessern.</span><br>\n    <span class=\"tlid-translation\">Mein Kurs ist für alle geeignet, unabhängig von Fähigkeiten und Fitnessniveau!</span>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <span class=\"tlid-translation\">Ich freue mich darauf, mit Ihnen zu trainieren!</span>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <span class=\"tlid-translation\">Ihre Hannah Kelly</span>\n</p></div></div>    </div>\n            \n        <div class=\"content-column last\" style=\"width: 49%;\">\n        <div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left image-full\">\n<img sizes=\"(min-width: 519px) 519px, 100vw\" src=\"/media/i6891009e5a54ca50.jpg\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div><div class=\"content-block n formatted-text \"><p>\n    <strong>Was Sie brauchen und mitbringen sollten:</strong><br>\n    <span class=\"tlid-translation\">Bequeme Kleidung</span><br>\n    <span class=\"tlid-translation\">und ganz wichtig eine Yoga- oder Pilatesmatte.</span>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <strong><span class=\"tlid-translation\">Feedback von meinen Kunden:</span></strong><br>\n    <span class=\"tlid-translation\">\"<i>Ich bin so dankbar für deine Lektion! Ich mache seit letztem Jahr Pilates, aber es macht wirklich einen riesigen Unterschied, wenn deine Lehrerin eine\n    professionelle Tänzerin ist und sich auf jede einzelne Bewegung, die du machst konzentrieren kann. Ich fühle mich sehr motiviert! \"</i>    <strong>Ceclia</strong></span>\n</p>\n\n<p>\n    <span class=\"tlid-translation\"> </span>\n</p>\n\n<p>\n     \n</p>\n\n<p>\n    <span class=\"tlid-translation\">„<i>Pilates hilft mir, mich zu beruhigen und zu zentrieren. Seit ich mit Hannah angefangen habe Pilates zu trainieren, habe ich eine neue Ebene des\n    Körperbewusstseins erreicht. Nach Jahren des normalen Fitnesstrainings empfinde ich Pilates als eine viel effektivere und umfassendere Form des Trainings. Ich spüre, dass meine Muskeln viel\n    ausgeglichener und effektiver trainiert werden, und erlebe dadurch eine extreme Verbesserung meiner Haltung und meiner Flexibilität. Danke!!!“</i>    <strong>Florian</strong></span>\n</p></div></div>    </div>\n    \n\n\n<br class=\"clear\">\n\n</div><div class=\"content-block n action-block \"><div class=\"action-wrapper action-align\">\n    <a class=\"action-link action-link\" data-action=\"button\" href=\"/contact/dance\" target=\"_blank\" data-title=\"Anmeldung Schnupperstunde\">\n        Anmeldung Schnupperstunde    </a>\n</div>\n</div></div>',1,1,'2020-10-02 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (6,'Alles für Eure Party!','everything-for-your-party','news/alles-fuer-eure-party','/media/i5db0681530b036e0.jpg','Ob Schuleinführung, Jugendweihe, Geburtstags- oder Gartenparty, wir haben das richtige Equipment für jeden Anlass. In unserem Netzwerk verfügen wir über eine große Menge an Veranstaltungsequipment, für kleine und große Events, welches bei uns günstig zu mieten ist. Wir freuen uns auf eure Anfrage. Euer Team vom KuTa Werk','<div><div class=\"content-block n formatted-text \"><div>\n    Ob Schuleinführung, Jugendweihe, Geburtstags- oder Gartenparty, wir haben das richtige Equipment für jeden Anlass. In unserem Netzwerk verfügen wir über eine große Menge an\n    Veranstaltungsequipment, für kleine und große Events, welches bei uns günstig zu mieten ist. \n</div>\n\n<div>\n    Wir freuen uns auf eure Anfrage. \n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Euer Team vom KuTa Werk \n</div></div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left image-full\">\n<img sizes=\"(min-width: 1000px) 1000px, 100vw\" src=\"/media/i5db0681530b036e0.jpg\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div><div class=\"content-block n j-sharebuttons \">\n<div class=\"cc-sharebuttons-element cc-sharebuttons-size-32 cc-sharebuttons-style-colored cc-sharebuttons-design-round cc-sharebuttons-align-center\">\n\n\n    <a class=\"cc-sharebuttons-facebook\" href=\"http://www.facebook.com/sharer.php?u=https://www.kutawerk.de/2020/08/05/alles-f%C3%BCr-eure-party/&amp;t=Alles%20f%C3%BCr%20Eure%20Party%21\" title=\"Facebook\" target=\"_blank\"></a><a class=\"cc-sharebuttons-mail\" href=\"https://www.kutawerk.de/cdn-cgi/l/email-protection#dee1adabbcb4bbbdaae39fb2b2bbadfbeceeb8fb9dedfb9c9dacfbecee9babacbbfbecee8ebfacaaa7fbeceff8bfb3aee5bcb1baa7e3b6aaaaaeade4f1f1a9a9a9f0b5abaabfa9bbacb5f0babbf1eceeeceef1eee6f1eeebf1bfb2b2bbadf3b8fb9dedfb9c9dacf3bbabacbbf3aebfacaaa7f1\" title=\"E-Mail\" target=\"\"></a>\n\n</div>\n</div></div>',1,1,'2020-08-05 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (7,'Endlich wieder Zumba®!!!','zumba-is-back','news/endlich-wieder-zumba','/media/iaf2658673cc0f44f.jpg','Wir freuen uns euch mitteilen zu dürfen, dass wir endlich wieder Zumba® anbieten können! Mit Sandra Vogel wird ab dem neuen Schuljahr jeden Dienstag und Donnerstag wieder fleißig getanztund Kalorien verbrannt. Wir freuen uns über eure Teilnahme und bitten um kurze Voranmeldung per Mail an info@kutawerk.de Zumba® Trainingszeiten Dienstags 19:15 - 20:15 Uhr Donnerstag 19:00 - 20:00 Uhr','<div><div class=\"content-block n content-spacing-block \">\n    <div class=\"content-spacing\" style=\"height: 5px;\">\n    \n</div>\n\n</div><div class=\"content-block n formatted-text \">Wir freuen uns euch mitteilen zu dürfen, dass wir endlich wieder Zumba® anbieten können! Mit Sandra Vogel wird ab dem neuen Schuljahr jeden Dienstag und Donnerstag wieder fleißig getanztund\nKalorien verbrannt.<br>\nWir freuen uns über eure Teilnahme und bitten um kurze Voranmeldung per Mail an <a href=\"https://www.kutawerk.de/cdn-cgi/l/email-protection#6317020d191013021117062308161702140611084d0706\" title=\"\"><span class=\"__cf_email__\" data-cfemail=\"f581949b8f868594878190b59e8081948290879edb9190\" href=\"mailto:tanzsparte@kutawerk.de\">tanzsparte@kutawerk.de</span></a><br>\n<br>\n<b>Zumba® Trainingszeiten</b><br>\nDienstags      19:15 - 20:15 Uhr<br>\nDonnerstag   19:00 - 20:00 Uhr</div><div class=\"content-block n content-spacing-block \">\n    <div class=\"content-spacing\" style=\"height: 15px;\">\n    \n</div>\n\n</div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left image-full\">\n<img sizes=\"(min-width: 1000px) 1000px, 100vw\" src=\"/media/iaf2658673cc0f44f.jpg\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div><div class=\"content-block n j-sharebuttons \">\n<div class=\"cc-sharebuttons-element cc-sharebuttons-size-64 cc-sharebuttons-style-colored cc-sharebuttons-design-round cc-sharebuttons-align-left\">\n\n\n    <a class=\"cc-sharebuttons-facebook\" href=\"http://www.facebook.com/sharer.php?u=https://www.kutawerk.de/2020/07/31/endlich-wieder-zumba/&amp;t=Endlich%20wieder%20Zumba%C2%AE%21%21%21\" title=\"Facebook\" target=\"_blank\"></a><a class=\"cc-sharebuttons-mail\" href=\"https://www.kutawerk.de/cdn-cgi/l/email-protection#e6d99593848c838592dba388828a8f858ec3d4d6918f83828394c3d4d6bc938b8487c3a5d4c3a7a3c3d4d7c3d4d7c3d4d7c0878b96dd8489829fdb8e92929695dcc9c9919191c88d9392879183948dc88283c9d4d6d4d6c9d6d1c9d5d7c98388828a8f858ecb918f83828394cb9c938b8487c9\" title=\"E-Mail\" target=\"\"></a>\n\n</div>\n</div></div>',1,1,'2020-07-31 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (8,'Trainingsbetrieb wieder aufgenommen - Coronatrainingsplan','coronavirus-training-schedule','news/corona-trainingsplan','/media/ie84d2dc316efa6ca.jpg','Yeah, endlich wieder tanzen. Das geht jedoch nur unter strickten Hygieneauflage. Doch wir sind froh endlich wieder beginnen zu können.','<div><div class=\"content-block n formatted-text \"><i>Yeah, endlich wieder tanzen. Das geht jedoch nur unter strickten Hygieneauflage. Doch wir sind froh endlich wieder beginnen zu können. </i></div><div class=\"content-block n text-image \"><figure class=\"image-frame image-left image-full\">\n<img sizes=\"(min-width: 210px) 210px, 100vw\" src=\"/media/ie84d2dc316efa6ca.jpg\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n<div>\n    <div data-name=\"text\" data-action=\"text\" class=\"formatted-text-inline\">\n        Hier alle wichtigen Fakten auf einen Schlag:<br>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Vielleicht habt Ihr selber schon gehört, dass es ab dieser Woche wieder möglich ist, im Verein an der frischen Luft Sport zu treiben. Auch wir möchten unseren TänzerInnen die Möglichkeit bieten,\n    sich draußen zu bewegen. Dies stellt allerdings einen hohen organisatorischen Aufwand dar, deswegen möchten wir nichts überstürzen und fangen mit unserem <b>Outdoor Training</b> erst in der\n    Woche vom <b>11.05</b>. an. \n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Glücklicherweise steht uns das große <b>Gelände an der KuTa-Lounge (Dresdner Str. 357)</b> zur Verfügung. Wir möchten in den nächsten Wochen versuchen, an diesem Ort langsam den Trainingsbetrieb\n    wieder zum Laufen zu bringen. \n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Natürlich müssen wir immer noch darauf achten, dass die Hygienemaßnahmen eingehalten werden. Dies bedeutet im Konkreten, dass: \n</div>\n\n<div>\n    - wir bei Gruppen mit vielen Mitgliedern, die Gruppenstärke minimieren müssen, sprich die <b>Gruppen aufteilen </b>werden\n</div>\n\n<div>\n    - die <b>Abstands- Hygiene- und Körperkontaktlosigkeitsregeln eingehalten</b> werden müssen \n</div>\n\n<div>\n    - alle TänzerInnen fertig umgezogen kommen müssen <b>(Umkleiden und Toiletten dürfen nicht genutzt werden)</b>\n</div>\n\n<div>\n    - sich die TänzerInnen nur zu ihrer entsprechenden Trainingszeit auf dem Gelände befinden dürfen (also bitte <b>nicht deutlich zu früh kommen</b>)\n</div>\n\n<div>\n    - <b>keine zusätzlichen Personen</b> beim Training zuschauen können (auch keine Eltern)\n</div>\n\n<div>\n    - <b>diejenigen, die sich krank fühlen</b>, bitte zum Schutz der Anderen <b>nicht zum Training erscheinen</b>\n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Es ist auch für uns eine ganz neue Erfahrung, die wir nur durch Ausprobieren machen können. In unserer Testphase möchten wir deshalb <b>alle Trainings auf 45 Minuten</b> begrenzen. Am Anfang\n    werden auch die Gruppen, die sonst öfters in der Woche Training hätten, <b>nur eine 45-minütige Trainingszeit pro Woche</b> haben. Außerdem werden in der ersten Phase auch <b>nur Gruppen ab dem\n    Schulalter</b> an den Trainingseinheiten teilnehmen können. Für jüngere Kinder können wir das Abstandsgebot leider zum aktuellen Zeitpunkt nicht gewährleisten. Dies betrifft die Gruppen\n    Ballettis, Ladybugs, Fireflies und Night Sky. \n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Aus diesen vielen Auflagen ergeben sich natürlich auch Änderungen im Trainingsplan. Wir haben versucht, wenn es uns möglich war, die regulären Trainingszeiten der Gruppen beizubehalten, dies ist\n    aber im Gesamten nicht für alle möglich.\n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Wir freuen uns sehr, Euch endlich wieder zu sehen und mit Euch gemeinsam tanzen zu können! \n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Liebe Grüße und bleibt weiterhin gesund! \n</div>\n\n<div>\n    <br>\n</div>\n\n<div>\n    Euer KuTa-Werk\n</div>    </div>\n</div>\n\n<div class=\"clear\"></div>\n</div><div class=\"content-block n j-sharebuttons \">\n<div class=\"cc-sharebuttons-element cc-sharebuttons-size-32 cc-sharebuttons-style-colored cc-sharebuttons-design-round cc-sharebuttons-align-center\">\n\n\n    <a class=\"cc-sharebuttons-facebook\" href=\"http://www.facebook.com/sharer.php?u=https://www.kutawerk.de/2020/05/08/trainingsbetrieb-wieder-aufgenommen-coronatrainingsplan/&amp;t=Trainingsbetrieb%20wieder%20aufgenommen%20-%20Coronatrainingsplan\" title=\"Facebook\" target=\"_blank\"></a><a class=\"cc-sharebuttons-x\" href=\"https://x.com/share?text=Trainingsbetrieb%20wieder%20aufgenommen%20-%20Coronatrainingsplan&amp;url=https%3A%2F%2Fwww.kutawerk.de%2F2020%2F05%2F08%2Ftrainingsbetrieb-wieder-aufgenommen-coronatrainingsplan%2F\" title=\"X\" target=\"_blank\"></a><a class=\"cc-sharebuttons-mail\" href=\"https://www.kutawerk.de/cdn-cgi/l/email-protection#\" title=\"E-Mail\" target=\"\"></a>\n\n</div>\n</div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left\">\n<img sizes=\"(min-width: 884px) 884px, 100vw\" src=\"/media/i5682169c47fd90b6.jpg\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left image-full\">\n<img sizes=\"(min-width: 1000px) 1000px, 100vw\" src=\"/media/i258e76597c73607b.jpg\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div></div>',1,1,'2020-05-08 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (9,'Trainingsbetrieb der Tanzsparte eingestellt','dance-training-suspended','news/trainingsbetrieb-eingestellt','/media/i98b5afad3e842875.jpg','Aufgrund der aktuellen Situation haben wir uns entschlossen, ab Montag, den 16.03.2020, bis nach den Osterferien unseren regulären Trainingsbetrieb einzustellen. Für nähere Informationen oder bei Fragen, bitten wir unser Kontaktformular der Tanzsparte zu benutzen. Lasst uns das gesellschaftliche Leben aufrechterhalten und zusammenhalten, aber tragt auch an der Verantwortung mit, die Ausbreitung des Virus zu verlangsamen, schränkt eure sozialen Kontakte vorerst auf das Nötigste ein! Bleibt...','<div><div class=\"content-block n formatted-text \"><div style=\"text-align: left;\">\n    <span style=\"-webkit-text-size-adjust: 100%;\">Aufgrund der aktuellen Situation haben wir uns entschlossen, ab Montag, den 16.03.2020, bis nach den Osterferien unseren regulären Trainingsbetrieb\n    einzustellen. </span>\n</div>\n\n<div style=\"text-align: left;\">\n    <span style=\"-webkit-text-size-adjust: 100%;\">Für nähere Informationen oder bei Fragen, bitten wir unser Kontaktformular der Tanzsparte zu benutzen.</span>\n</div>\n\n<div style=\"text-align: left;\">\n    <br>\n</div>\n\n<div style=\"text-align: left;\">\n    <span style=\"-webkit-text-size-adjust: 100%;\">Lasst uns das gesellschaftliche Leben aufrechterhalten und zusammenhalten, aber tragt auch an der Verantwortung mit, die Ausbreitung des Virus zu\n    verlangsamen, schränkt eure sozialen Kontakte vorerst auf das Nötigste ein! Bleibt gesund! </span>\n</div>\n\n<div style=\"text-align: left;\">\n    <span style=\"-webkit-text-size-adjust: 100%;\">Herzlich, Euer Tanzsparten-Leitungsteam</span>\n</div></div><div class=\"content-block n image-gallery \">\n</div><div class=\"content-block n j-sharebuttons \">\n<div class=\"cc-sharebuttons-element cc-sharebuttons-size-32 cc-sharebuttons-style-colored cc-sharebuttons-design-round cc-sharebuttons-align-left\">\n\n\n    <a class=\"cc-sharebuttons-facebook\" href=\"http://www.facebook.com/sharer.php?u=https://www.kutawerk.de/2020/03/15/trainingsbetrieb-der-tanzsparte-eingestellt/&amp;t=Trainingsbetrieb%20der%20Tanzsparte%20eingestellt\" title=\"Facebook\" target=\"_blank\"></a><a class=\"cc-sharebuttons-x\" href=\"https://x.com/share?text=Trainingsbetrieb%20der%20Tanzsparte%20eingestellt&amp;url=https%3A%2F%2Fwww.kutawerk.de%2F2020%2F03%2F15%2Ftrainingsbetrieb-der-tanzsparte-eingestellt%2F\" title=\"X\" target=\"_blank\"></a>\n\n</div>\n</div></div>[[NEWS_GALLERY]]',1,1,'2020-03-15 12:00:00',NULL,NULL,NULL);
INSERT  IGNORE INTO `news_posts` (`id`, `title`, `slug`, `legacy_key`, `image_path`, `excerpt`, `content`, `content_is_html`, `published`, `published_at`, `visible_from`, `visible_until`, `author_id`) VALUES (10,'KuTaWards - Veranstaltung verschoben - auf 21.03.2021','kutawards-postponed','news/kutawards-verschoben','/media/iab39ac35c5a1d052.jpg','Liebe Mitglieder, liebe Eltern, liebe Zuschauer! Der Termin für KuTaWards wird vom 22.03.20 auf den 21.03.21 verschoben. Nach vielen Gesprächen, Gedanken und Überlegungen haben wir uns entschieden, dass es aus der Perspektive eines verantwortungsbewussten Veranstalters notwendig ist die Veranstaltungzuverschieben.Aufgeschoben ist nicht aufgehoben! Bleibt alle motiviert und gesund, herzlich Euer Vorstand und das Trainer-Team des KuTaWerks *bereits getätigte Karten Reservierungen bleiben...','<div><div class=\"content-block n formatted-text \">Liebe Mitglieder, liebe Eltern, liebe Zuschauer!<br>\n<b>Der Termin für KuTaWards wird vom 22.03.20 auf den 21.03.21 verschoben.</b><br>\nNach vielen Gesprächen, Gedanken und Überlegungen haben wir uns entschieden, dass es aus der Perspektive eines verantwortungsbewussten Veranstalters notwendig ist die\nVeranstaltungzuverschieben.Aufgeschoben ist nicht aufgehoben!<br>\nBleibt alle motiviert und gesund, herzlich Euer Vorstand und das Trainer-Team des KuTaWerks<br>\n<br>\n<i>*bereits getätigte Karten Reservierungen bleiben bestehen - bei Änderungen kontaktieret uns bitte über <a href=\"mailto:info@kutawerk.de\" class=\"__cf_email__\" data-cfemail=\"bad3d4dcd5fad1cfcedbcddfc8d194dedf\">info@kutawerk.de</a></i></div><div class=\"content-block n image-block \"><figure class=\"image-frame image-left image-full\">\n<img sizes=\"(min-width: 1000px) 1000px, 100vw\" src=\"/media/iab39ac35c5a1d052.jpg\" alt=\"\" class=\"\" loading=\"lazy\">    \n\n</figure>\n\n<div class=\"clear\"></div>\n</div><div class=\"content-block n j-sharebuttons \">\n<div class=\"cc-sharebuttons-element cc-sharebuttons-size-32 cc-sharebuttons-style-colored cc-sharebuttons-design-round cc-sharebuttons-align-center\">\n\n\n    <a class=\"cc-sharebuttons-facebook\" href=\"http://www.facebook.com/sharer.php?u=https://www.kutawerk.de/2020/03/10/kutawards-veranstaltung-verschoben-auf-21-06-2020/&amp;t=KuTaWards%20-%20Veranstaltung%20verschoben%20-%20auf%2021.03.2021\" title=\"Facebook\" target=\"_blank\"></a><a class=\"cc-sharebuttons-mail\" href=\"https://www.kutawerk.de/cdn-cgi/l/email-protection#\" title=\"E-Mail\" target=\"\"></a>\n\n</div>\n</div></div>',1,1,'2020-03-10 12:00:00',NULL,NULL,NULL);
